https://bit.ly/2Ul51rV. 

附錄一、LinkIt 7697 程式碼 

//MCS 可《開關門鎖》，顯示《次數統計》、顯示《LED 開 / 關》 
//NFC 可控制 

#include <LWiFi.h> 
#include <WiFiClient.h> 
#include "MCS.h" 

#include <Wire.h> // 讀取NFC 函數庫 
#include <SPI.h> 
#include <Adafruit_PN532.h> 
#include <Servo.h> // 讀取馬達函數庫 

// 宣告各個WIFI 的SSID 名稱和密碼 
//● 1- 手機基地台 
//#define _SSID "teAllen-HTC" 
//#define _KEY "0921580660" 

//● 2- 家中WIFI 
#define _SSID "ASUS-1F-2018" 
#define _KEY "0921580660" 

//宣告在MCS 中的測試裝置的ID 以及KEY 
MCSDevice mcs("Df0GQ9Z8", "sT5iAdeSs3dOCVPv"); 

// 宣告測試裝置中各個測試通道的ID 
MCSControllerOnOff led("MyLockDoor");//遠端控制門鎖開或關的控制通道 
MCSDisplayInteger remote("MyLockDoorReturn");//紀錄開門次數 
MCSDisplayOnOff doorstate("DoorState");//顯示門鎖目前是開或關的顯示通道 
#define PN532_SCK (13) // 定義Adafruit_PN532 SPI 介面 
#define PN532_MOSI (11) 
#define PN532_SS (10) 
#define PN532_MISO (12) 
Adafruit_PN532 nfc(PN532_SCK, PN532_MISO, PN532_MOSI, PN532_SS); 

Servo myservo; // 定義myservo 
int servoPin = 5; // 設定p5 控制Servo/電磁鎖 
int switchPin = 3; // 設定p3 控制警報聲開關 
int piezoPin = 4; // 設定p4 控制蜂鳴器 

int lockState = 1; // 如果為1, 鎖門,如果為 0, 開門 

#define LED_PIN 7 
int ledcount=0; 
int temp=0; 

//--------------------------------------------------------- 
void setup() { 
 // 序列埠監控視窗 

 Serial.begin(9600); // 設定至9600 鲍率 

 // 設置警報聲的針腳 
pinMode(switchPin,INPUT); 
pinMode(piezoPin,OUTPUT); 

 // 設置LED 的針腳 
 pinMode(LED_PIN, OUTPUT); 

 // 將LinkIt7697 連上指定的WIFI 
 while(WL_CONNECTED != WiFi.status()) 
 { 

 Serial.print("WiFi.begin("); 
 Serial.print(_SSID); 
 Serial.print(","); 
 Serial.print(_KEY); 
 Serial.println(")..."); 

 WiFi.begin(_SSID, _KEY); 
 } 
 //Serial.println("WiFi connected !!"); 

 // 將LinkIt7697 與MCS 的各個資料通道進行連線 
 mcs.addChannel(led); 
 mcs.addChannel(remote); 
 mcs.addChannel(doorstate); 
 mcs.addChannel(alarm); 
 while(!mcs.connected()) 
 { 
 Serial.println("MCS.connect()..."); 
 mcs.connect(); 
 } 
 Serial.println("MCS connected !!"); 

 //從MCS 上讀取開關的值 
 while(!led.valid()) 
 { 
 Serial.println("read LED value from MCS..."); 
 led.value(); 
 } 
 Serial.print("done, LED value = "); 
 Serial.println(led.value()); 
 digitalWrite(LED_PIN, led.value() ? HIGH : LOW); 

 // Serial.println("Hello!"); // 連線NFC Adafruit RFID/NFC 
 nfc.begin(); 
 pinMode(LED_BUILTIN,OUTPUT); 
 uint32_t versiondata = nfc.getFirmwareVersion(); 
 if (! versiondata) { 
// Serial.print("未找到 PN53x 板"); 
 while (1); // 不斷重覆 
 } 

 // 取得回傳資料 
 Serial.print("找到晶片 PN5"); Serial.println((versiondata>>24) & 0xFF, HEX); 
 Serial.print("?體版本. "); Serial.print((versiondata>>16) & 0xFF, DEC); 
 Serial.print('.'); Serial.println((versiondata>>8) & 0xFF, DEC); 
 // 設定與讀取NFC 
 nfc.SAMConfig(); 

} 
//--------------------------------------------------------- 
void loop() { 
 // 1. 連線MCS 
 MCS_Connect(); 

 // 2. 連線NFC 
 NFC_Connect(); 
 } 

void MCS_Connect(){ 
 mcs.process(100); 
 if(temp!=led.value()){ 
 lockUnlock(led.value()); //將開關值0, 1 傳遞，作馬達/電磁鎖控制動作 
 temp=led.value(); 
 Serial.println(led.value()); 
 delay(2000); 
} 
int switchState = alarm.value(); //設定警報器開/關 
if (switchState == HIGH){ 
 tone(piezoPin,650,230); 
 delay(230); 
 noTone(piezoPin); 
 tone(piezoPin,1550,100); 
 delay(100); 
 noTone(piezoPin); 
} 
} 
//--------------------------------------------------------------------------- 
void NFC_Connect() { 
 // 設定與讀取NFC 
 uint8_t success; 
 uint8_t uid[] = { 0, 0, 0, 0, 0, 0, 0 }; 
 uint8_t uidLength; 
 success = nfc.readPassiveTargetID(PN532_MIFARE_ISO14443A, uid, &uidLength,1000); 
 uint32_t cardidentifier = 0; 

 if (success!=0 ) { 
 // 顯示NFC 卡的資訊 
 Serial.println("Found an ISO14443A card"); 
 Serial.println("Card detected #"); 

 cardidentifier = uid[3]; 
 cardidentifier <<= 8; cardidentifier |= uid[2]; //算術移位的運算子:左移8 bit 
 cardidentifier <<= 8; cardidentifier |= uid[1]; 
 cardidentifier <<= 8; cardidentifier |= uid[0]; 

 Serial.println(cardidentifier); 

 switch (cardidentifier) { 

case 10048155: // 白色NFC Tag 卡號（新） 
 lockUnlock(doorstate.value()+1); 
 delay(2000); 
 break; 

case 1806137733: // 藍色NFC Tag 卡號（新） 
 lockUnlock(doorstate.value()+1); 
 delay(2000); 
 break; 

case 3806422677: // 4. 白色NFC Tag 卡號 
 lockUnlock(lockState ); 
 delay(2000); 
 break; 

case 3545762402: // 3. 藍色磁扣NFC Tag 
 lockUnlock(lockState ); 
 delay(2000); 
 break; 

case 1973563880: // 2. 學校電梯卡 Tag 
 lockUnlock(lockState ); 
 delay(2000); 
 break; 

case 277283200: // 1. HTC Ultra 手機 Tag 
 lockUnlock(lockState ); 
 delay(2000); 
 break; 

case 16909060: // 1. HTC Ultra 手機 Tag 
 lockUnlock(lockState ); 
 delay(2000); 
 break; 

 default: 
 digitalWrite(13, HIGH); // 如果讀取到的卡號根以寫入的卡號不同 
 delay(100); // 則使13 腳的LED 燈亮，並持續0.1 秒 
 digitalWrite(13, LOW); 
 delay(100); 
 } //switch 
 } 
 success=0; 

 Serial.println("Switch 結束"); 
 Serial.println("NFC 結束"); 
} 
